use crate::{MssqlProvider, QueryRows, ToSql};
use std::{future::Future, pin::Pin};
use storm::{OnDelete, Result};
use tiberius::Row;

/// Mapping of an entity (columns, unique indexes and foreign keys), generated by `MssqlLoad`.
///
/// Used by [check_schema] to compare the model with the database.
pub trait MssqlSchema {
    const SCHEMA: EntitySchema;
}

#[derive(Clone, Copy, Debug)]
pub struct EntitySchema {
    pub table: &'static str,
    pub translated_table: &'static str,
    pub keys: &'static [&'static str],
    pub columns: &'static [ColumnSchema],
    pub uniques: &'static [UniqueSchema],
    pub foreign_keys: &'static [ForeignKeySchema],
    /// Only the mapped columns are checked: unique indexes and foreign keys are ignored.
    pub partial: bool,
}

#[derive(Clone, Copy, Debug)]
pub struct ColumnSchema {
    pub name: &'static str,
    pub field: &'static str,
    /// `0` when no `max_length` is declared.
    pub max_length: usize,
    /// The field is an `Option`, `None` when unknown (translated or `load_with` fields).
    pub nullable: Option<bool>,
    /// The column is in the translated table.
    pub translated: bool,
}

#[derive(Clone, Copy, Debug)]
pub struct UniqueSchema {
    pub name: &'static str,
    pub columns: &'static [&'static str],
    pub case_insensitive: bool,
    pub accent_insensitive: bool,
    pub filtered: bool,
}

#[derive(Clone, Copy, Debug)]
pub struct ForeignKeySchema {
    pub field: &'static str,
    pub column: &'static str,
    /// Table of the referenced (parent) entity.
    pub table: &'static str,
    pub on_delete: OnDelete,
}

/// Generated test (`test_{entity}_entity`) panicking when the model does not match the database.
#[doc(hidden)]
#[allow(clippy::expect_used)]
#[allow(clippy::panic)]
pub fn test_entity<E: MssqlSchema>(provider: &str) -> Pin<Box<dyn Future<Output = ()> + '_>> {
    Box::pin(async move {
        let container =
            crate::create_provider_container_from_env("DB", provider).expect("container");

        let provider = container
            .provide::<MssqlProvider>(provider)
            .await
            .expect("provider");

        let errors = check_schema(provider, &E::SCHEMA)
            .await
            .expect("check_schema");

        if !errors.is_empty() {
            panic!(
                "`{}` does not match the database:\n- {}",
                E::SCHEMA.table,
                errors.join("\n- ")
            );
        }
    })
}

/// Compares the model with the database and returns the differences:
///
/// - every mapped column must exist;
/// - every bounded text or binary column (`nvarchar(50)`, `varbinary(16)`, ...) must declare the
///   same `max_length`; unbounded columns (`nvarchar(max)`, `int`, ...) must not declare one;
/// - partial entities only: `Option` fields must match nullable columns;
/// - every unique index of the table must be declared on the model, with the same collation
///   and filtered or not (indexes containing the whole primary key are ignored);
/// - every single column foreign key of the table must be declared on the model, referencing
///   the same table with the same `on_delete`.
///
/// Unique indexes and foreign keys declared only on the model are allowed. They are not checked
/// for partial entities.
pub async fn check_schema(provider: &MssqlProvider, schema: &EntitySchema) -> Result<Vec<String>> {
    let mut errors = Vec::new();
    let table = DbTable::new(schema.table);

    let Some(table_id) = table.object_id(provider).await? else {
        errors.push(format!("table `{}` not found.", schema.table));
        return Ok(errors);
    };

    let columns = table.columns(provider, table_id).await?;

    let translated_columns = if schema.translated_table.is_empty() {
        Vec::new()
    } else {
        let translated = DbTable::new(schema.translated_table);

        match translated.object_id(provider).await? {
            Some(id) => translated.columns(provider, id).await?,
            None => {
                errors.push(format!(
                    "translated table `{}` not found.",
                    schema.translated_table
                ));
                Vec::new()
            }
        }
    };

    for column in schema.columns {
        let (table, columns) = match column.translated {
            true => (schema.translated_table, &translated_columns),
            false => (schema.table, &columns),
        };

        check_column(table, column, columns, schema.partial, &mut errors);
    }

    if schema.partial {
        return Ok(errors);
    }

    for index in table.uniques(provider, table_id).await? {
        check_unique(schema, &index, &mut errors);
    }

    for fk in table.foreign_keys(provider, table_id).await? {
        check_foreign_key(provider, schema, &fk, &mut errors).await?;
    }

    Ok(errors)
}

fn check_column(
    table: &str,
    column: &ColumnSchema,
    db_columns: &[DbColumn],
    check_nullable: bool,
    errors: &mut Vec<String>,
) {
    let field = column.field;

    let Some(db) = db_columns.iter().find(|c| same_name(&c.name, column.name)) else {
        if !db_columns.is_empty() {
            errors.push(format!(
                "field `{field}`: column `{}` not found in `{table}`.",
                column.name
            ));
        }
        return;
    };

    let ty = db.type_desc();

    match (db.bound(), column.max_length) {
        (Some(Some(n)), m) if n == m => {}
        (Some(Some(n)), 0) => errors.push(format!(
            "field `{field}`: column `{}` is {ty}, add `#[storm(max_length = {n})]`.",
            db.name
        )),
        (Some(Some(_)), m) => errors.push(format!(
            "field `{field}`: max_length = {m} but column `{}` is {ty}.",
            db.name
        )),
        (_, 0) => {}
        (_, m) => errors.push(format!(
            "field `{field}`: max_length = {m} but column `{}` is {ty}, remove `max_length`.",
            db.name
        )),
    }

    match column.nullable {
        Some(false) if check_nullable && db.nullable => errors.push(format!(
            "field `{field}`: column `{}` is nullable, use an `Option`.",
            db.name
        )),
        Some(true) if check_nullable && !db.nullable => errors.push(format!(
            "field `{field}`: column `{}` is not nullable, remove the `Option`.",
            db.name
        )),
        _ => {}
    }
}

fn check_unique(schema: &EntitySchema, index: &DbUnique, errors: &mut Vec<String>) {
    let has_column = |name: &str| index.columns.iter().any(|(c, _)| same_name(c, name));

    // always unique since the primary key is part of the index.
    if !schema.keys.is_empty() && schema.keys.iter().all(|k| has_column(k)) {
        return;
    }

    let model = schema.uniques.iter().find(|u| {
        u.columns.len() == index.columns.len() && u.columns.iter().all(|c| has_column(c))
    });

    let db_collation = index
        .columns
        .iter()
        .find_map(|(_, c)| c.as_deref())
        .map(parse_collation);

    let Some(model) = model else {
        let mut fields = Vec::new();

        for (column, _) in &index.columns {
            match schema.columns.iter().find(|c| same_name(c.name, column)) {
                Some(c) if !c.translated => fields.push(c.field),
                _ => {
                    errors.push(format!(
                        "unique index `{}` of `{}` is not declared on the model: column `{column}` is not mapped to a field.",
                        index.name, schema.table
                    ));
                    return;
                }
            }
        }

        let mut args = Vec::new();

        if fields.len() > 1 {
            args.push(format!("fields = \"{}\"", fields.join(", ")));
        }

        if let Some(c) = db_collation.filter(|c| *c != (true, false)) {
            args.push(format!("collation = \"{}\"", collation_name(c)));
        }

        if let Some(filter) = &index.filter {
            args.push(format!("filter = /* {filter} */"));
        }

        let attr = match (fields.len() > 1, args.is_empty()) {
            (false, true) => "#[storm(unique)]".to_owned(),
            _ => format!("#[storm(unique({}))]", args.join(", ")),
        };

        let target = match fields.len() > 1 {
            true => "on the type".to_owned(),
            false => format!("on field `{}`", fields[0]),
        };

        errors.push(format!(
            "unique index `{}` of `{}` is not declared on the model: add `{attr}` {target}.",
            index.name, schema.table
        ));
        return;
    };

    match (&index.filter, model.filtered) {
        (Some(filter), false) => errors.push(format!(
            "unique `{}`: index `{}` is filtered by `{filter}` but the model has no `filter`.",
            model.name, index.name
        )),
        (None, true) => errors.push(format!(
            "unique `{}`: the model has a `filter` but index `{}` is not filtered.",
            model.name, index.name
        )),
        _ => {}
    }

    let expected = (model.case_insensitive, model.accent_insensitive);

    for (column, collation) in &index.columns {
        let Some(collation) = collation else {
            continue;
        };

        let actual = parse_collation(collation);

        if actual != expected {
            errors.push(format!(
                "unique `{}`: collation = \"{}\" but column `{column}` is `{collation}` (collation = \"{}\").",
                model.name,
                collation_name(expected),
                collation_name(actual),
            ));
        }
    }
}

async fn check_foreign_key(
    provider: &MssqlProvider,
    schema: &EntitySchema,
    fk: &DbForeignKey,
    errors: &mut Vec<String>,
) -> Result<()> {
    // composite foreign keys cannot be declared on the model.
    let [column] = &fk.columns[..] else {
        return Ok(());
    };

    let db_on_delete = match fk.delete_action {
        0 => Some(OnDelete::Restrict),
        1 => Some(OnDelete::Cascade),
        2 => Some(OnDelete::SetNull),
        _ => None,
    };

    let Some(model) = schema
        .foreign_keys
        .iter()
        .find(|f| same_name(f.column, column))
    else {
        let field = schema
            .columns
            .iter()
            .find(|c| !c.translated && same_name(c.name, column));
        let is_key = schema.keys.iter().any(|k| same_name(k, column));

        errors.push(match field {
            Some(c) => format!(
                "foreign key `{}` ({column} -> {}) of `{}` is not declared on the model: add `#[storm(foreign_key(entity = ..., on_delete = \"{}\"))]` on field `{}`.",
                fk.name,
                fk.referenced_table,
                schema.table,
                db_on_delete.map_or("?", on_delete_name),
                c.field,
            ),
            None if is_key => format!(
                "foreign key `{}` ({column} -> {}) of `{}` is not declared on the model: add `#[storm(foreign_key(column = \"{column}\", entity = ..., on_delete = \"{}\"))]` on the type (with `key = <position>` for a composite key).",
                fk.name,
                fk.referenced_table,
                schema.table,
                db_on_delete.map_or("?", on_delete_name),
            ),
            None => format!(
                "foreign key `{}` ({column} -> {}) of `{}` is not declared on the model: column `{column}` is not mapped to a field.",
                fk.name, fk.referenced_table, schema.table,
            ),
        });

        return Ok(());
    };

    let parent_id = DbTable::new(model.table).object_id(provider).await?;

    if parent_id != Some(fk.referenced_id) {
        errors.push(format!(
            "field `{}`: references `{}` but foreign key `{}` references `{}`.",
            model.field, model.table, fk.name, fk.referenced_table
        ));
    }

    match db_on_delete {
        // the model may cascade / set null itself before the database checks the restriction.
        Some(on_delete) if on_delete == model.on_delete || on_delete == OnDelete::Restrict => {}
        Some(on_delete) => errors.push(format!(
            "field `{}`: on_delete = \"{}\" but foreign key `{}` is on_delete = \"{}\".",
            model.field,
            on_delete_name(model.on_delete),
            fk.name,
            on_delete_name(on_delete),
        )),
        None => errors.push(format!(
            "field `{}`: foreign key `{}` is ON DELETE SET DEFAULT, which is not supported.",
            model.field, fk.name
        )),
    }

    Ok(())
}

fn collation_name((ci, ai): (bool, bool)) -> &'static str {
    match (ci, ai) {
        (false, false) => "exact",
        (true, false) => "ci",
        (false, true) => "ai",
        (true, true) => "ai_ci",
    }
}

fn on_delete_name(on_delete: OnDelete) -> &'static str {
    match on_delete {
        OnDelete::Cascade => "cascade",
        OnDelete::Restrict => "restrict",
        OnDelete::SetNull => "set_null",
    }
}

/// (case insensitive, accent insensitive) of a SQL Server collation.
fn parse_collation(collation: &str) -> (bool, bool) {
    let c = collation.to_uppercase();

    if c.contains("_BIN") {
        return (false, false);
    }

    (c.contains("_CI"), c.contains("_AI"))
}

fn same_name(a: &str, b: &str) -> bool {
    let trim = |s: &str| s.trim_matches(['[', ']']).to_lowercase();
    trim(a) == trim(b)
}

fn get_str(row: &Row, index: usize) -> Result<Option<String>> {
    Ok(row.try_get::<&str, _>(index)?.map(str::to_owned))
}

struct DbTable {
    /// Name given to `OBJECT_ID`.
    lookup: String,

    /// Catalog views prefix (`sys.`, `tempdb.sys.`, `[db].sys.`).
    sys: String,
}

impl DbTable {
    fn new(name: &str) -> Self {
        let parts = name.split('.').collect::<Vec<_>>();
        let last = parts
            .last()
            .copied()
            .unwrap_or_default()
            .trim_matches(['[', ']']);

        if last.starts_with('#') {
            return Self {
                lookup: format!("tempdb..{last}"),
                sys: "tempdb.sys.".to_owned(),
            };
        }

        let sys = match &parts[..] {
            [db, _, _] => format!("[{}].sys.", db.trim_matches(['[', ']'])),
            _ => "sys.".to_owned(),
        };

        Self {
            lookup: name.to_owned(),
            sys,
        }
    }

    async fn object_id(&self, provider: &MssqlProvider) -> Result<Option<i32>> {
        let name: &str = &self.lookup;
        let params: [&dyn ToSql; 1] = [&name];

        let rows: Vec<Option<i32>> = provider
            .query_rows(
                "SELECT OBJECT_ID(@P1)".to_owned(),
                &params,
                |row| Ok(row.try_get::<i32, _>(0)?),
                false,
            )
            .await?;

        Ok(rows.into_iter().next().flatten())
    }

    async fn columns(&self, provider: &MssqlProvider, id: i32) -> Result<Vec<DbColumn>> {
        let sql = format!(
            "SELECT c.name, TYPE_NAME(c.system_type_id), CAST(c.max_length AS int), c.is_nullable
            FROM {sys}columns c
            WHERE c.object_id = @P1",
            sys = self.sys
        );

        provider
            .query_rows(
                sql,
                &[&id],
                |row| {
                    Ok(DbColumn {
                        name: get_str(&row, 0)?.unwrap_or_default(),
                        ty: get_str(&row, 1)?.unwrap_or_default(),
                        max_length: row.try_get::<i32, _>(2)?.unwrap_or_default(),
                        nullable: row.try_get::<bool, _>(3)?.unwrap_or_default(),
                    })
                },
                false,
            )
            .await
    }

    async fn uniques(&self, provider: &MssqlProvider, id: i32) -> Result<Vec<DbUnique>> {
        let sql = format!(
            "SELECT i.name, i.filter_definition, c.name, c.collation_name
            FROM {sys}indexes i
            INNER JOIN {sys}index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id
            INNER JOIN {sys}columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id
            WHERE i.object_id = @P1 AND i.is_unique = 1 AND i.is_primary_key = 0
                AND i.is_disabled = 0 AND i.is_hypothetical = 0 AND ic.key_ordinal > 0
            ORDER BY i.name, ic.key_ordinal",
            sys = self.sys
        );

        let rows: Vec<(String, Option<String>, String, Option<String>)> = provider
            .query_rows(
                sql,
                &[&id],
                |row| {
                    Ok((
                        get_str(&row, 0)?.unwrap_or_default(),
                        get_str(&row, 1)?,
                        get_str(&row, 2)?.unwrap_or_default(),
                        get_str(&row, 3)?,
                    ))
                },
                false,
            )
            .await?;

        let mut out: Vec<DbUnique> = Vec::new();

        for (name, filter, column, collation) in rows {
            match out.last_mut().filter(|u| u.name == name) {
                Some(u) => u.columns.push((column, collation)),
                None => out.push(DbUnique {
                    name,
                    filter,
                    columns: vec![(column, collation)],
                }),
            }
        }

        Ok(out)
    }

    async fn foreign_keys(&self, provider: &MssqlProvider, id: i32) -> Result<Vec<DbForeignKey>> {
        let sql = format!(
            "SELECT fk.name, CAST(fk.delete_referential_action AS int), c.name, s.name + '.' + t.name, fk.referenced_object_id
            FROM {sys}foreign_keys fk
            INNER JOIN {sys}foreign_key_columns fkc ON fkc.constraint_object_id = fk.object_id
            INNER JOIN {sys}columns c ON c.object_id = fkc.parent_object_id AND c.column_id = fkc.parent_column_id
            INNER JOIN {sys}tables t ON t.object_id = fk.referenced_object_id
            INNER JOIN {sys}schemas s ON s.schema_id = t.schema_id
            WHERE fk.parent_object_id = @P1 AND fk.is_disabled = 0
            ORDER BY fk.name, fkc.constraint_column_id",
            sys = self.sys
        );

        let rows: Vec<(String, i32, String, String, i32)> = provider
            .query_rows(
                sql,
                &[&id],
                |row| {
                    Ok((
                        get_str(&row, 0)?.unwrap_or_default(),
                        row.try_get::<i32, _>(1)?.unwrap_or_default(),
                        get_str(&row, 2)?.unwrap_or_default(),
                        get_str(&row, 3)?.unwrap_or_default(),
                        row.try_get::<i32, _>(4)?.unwrap_or_default(),
                    ))
                },
                false,
            )
            .await?;

        let mut out: Vec<DbForeignKey> = Vec::new();

        for (name, delete_action, column, referenced_table, referenced_id) in rows {
            match out.last_mut().filter(|f| f.name == name) {
                Some(f) => f.columns.push(column),
                None => out.push(DbForeignKey {
                    name,
                    delete_action,
                    columns: vec![column],
                    referenced_table,
                    referenced_id,
                }),
            }
        }

        Ok(out)
    }
}

struct DbColumn {
    name: String,
    ty: String,
    max_length: i32,
    nullable: bool,
}

impl DbColumn {
    /// `None`: not a text or binary column, `Some(None)`: unbounded, `Some(Some(n))`: bounded.
    fn bound(&self) -> Option<Option<usize>> {
        let unit = match self.ty.as_str() {
            "nchar" | "nvarchar" => 2,
            "char" | "varchar" | "binary" | "varbinary" => 1,
            "text" | "ntext" | "image" => return Some(None),
            _ => return None,
        };

        Some(match self.max_length {
            -1 => None,
            n => Some(n as usize / unit),
        })
    }

    fn type_desc(&self) -> String {
        match self.bound() {
            Some(Some(n)) => format!("{}({n})", self.ty),
            Some(None) if self.max_length == -1 => format!("{}(max)", self.ty),
            _ => self.ty.clone(),
        }
    }
}

struct DbUnique {
    name: String,
    filter: Option<String>,
    /// (column, collation)
    columns: Vec<(String, Option<String>)>,
}

struct DbForeignKey {
    name: String,
    /// 0: no action, 1: cascade, 2: set null, 3: set default.
    delete_action: i32,
    columns: Vec<String>,
    referenced_table: String,
    referenced_id: i32,
}
